syntax:
// RVO: Returning an unnamed temporary
MyClass createObject() {
    return MyClass(); // The compiler constructs the object directly in the caller's scope
}

// NRVO: Returning a named object
MyClass createNamedObject() {
    MyClass obj;
    // ... operations on obj ...
    return obj; // The compiler might construct 'obj' directly in the caller's scope
}

code_example:
#include <iostream>

struct MyClass {
    MyClass() { std::cout << "Default constructor\n"; }
    MyClass(const MyClass&) { std::cout << "Copy constructor\n"; }
    ~MyClass() { std::cout << "Destructor\n"; }
};

MyClass createObject_RVO() {
    return MyClass(); // RVO is applied here
}

MyClass createObject_NRVO() {
    MyClass obj;
    return obj; // NRVO is applied here
}

int main() {
    std::cout << "Calling createObject_RVO:\n";
    MyClass obj1 = createObject_RVO();
    std::cout << "\nCalling createObject_NRVO:\n";
    MyClass obj2 = createObject_NRVO();
    std::cout << "\nExiting main...\n";
    return 0;
}
